using System.Net.Http.Headers; using Hyper.Domain.Entities.Integrations; using Hyper.Domain.Features.Integrations; namespace Hyper.Infrastructure.Features.Integrations; public abstract class ExternalIntegrationAdapterBase(IHttpClientFactory clients) : IExternalIntegrationAdapter { public abstract IntegrationProvider Provider { get; } protected HttpClient Client=>clients.CreateClient("ExternalIntegrations"); protected static void ApplyCorrelation(HttpRequestMessage request,string? correlationId){if(!string.IsNullOrWhiteSpace(correlationId))request.Headers.TryAddWithoutValidation("X-Correlation-ID",correlationId);} public abstract Task<IReadOnlyCollection<ExternalCatalogItem>> ReadCatalogAsync(ExternalIntegrationConnection connection,CancellationToken cancellationToken); public abstract Task PublishInventoryAsync(ExternalIntegrationConnection connection,IReadOnlyCollection<ExternalProductMapping> mappings,CancellationToken cancellationToken); } public class BasalamIntegrationAdapter(IHttpClientFactory clients) : ExternalIntegrationAdapterBase(clients) { public override IntegrationProvider Provider=>IntegrationProvider.Basalam; public override Task<IReadOnlyCollection<ExternalCatalogItem>> ReadCatalogAsync(ExternalIntegrationConnection connection,CancellationToken cancellationToken)=>Task.FromResult<IReadOnlyCollection<ExternalCatalogItem>>(Array.Empty<ExternalCatalogItem>()); public override Task PublishInventoryAsync(ExternalIntegrationConnection connection,IReadOnlyCollection<ExternalProductMapping> mappings,CancellationToken cancellationToken)=>Task.CompletedTask; } public sealed class DigikalaIntegrationAdapter(IHttpClientFactory clients) : BasalamIntegrationAdapter(clients) { public override IntegrationProvider Provider=>IntegrationProvider.Digikala; } public sealed class TorobIntegrationAdapter(IHttpClientFactory clients) : BasalamIntegrationAdapter(clients) { public override IntegrationProvider Provider=>IntegrationProvider.Torob; }
